  float h = winHash(cell, vSeed);
  float lit = step(0.47, h);
  float hue = winHash(cell + 3.0, vSeed + 1.0);
  vec3 warm = vec3(1.0, 0.72, 0.38);
  vec3 cool = vec3(0.45, 0.82, 1.0);
  vec3 neon = vec3(1.0, 0.32, 0.78);
  vec3 c = mix(warm, cool, step(0.55, hue));
  c = mix(c, neon, step(0.9, hue));
  emis = c * lit * (0.7 + 0.9*hue) * 2.2;
  // base glow at street level
  float base = smoothstep(0.14, 0.0, uv.y) * side;
  emis += vec3(0.2, 0.75, 1.0) * base * 0.5 * step(0.5, winHash(vec2(floor(uv.x*4.0), vSeed), 2.0));
}
```
