/**
 * Fully procedural audio: engine, tyres, wind, impacts, pickups and a
 * generated synthwave loop. No audio files, so it works offline.
 */
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.ready = false
    this.muted = false
    this.musicPlaying = false
    this.step = 0
    this.nextNoteTime = 0
    this.timer = null
    this.driftAmount = 0
    this.speedNorm = 0
  }

  async init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume().catch(() => {})
      return
    }
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    try {
      const ctx = new AC()
      this.ctx = ctx
      if (ctx.state === 'suspended') await ctx.resume().catch(() => {})

      this.master = ctx.createGain()
      this.master.gain.value = this.muted ? 0 : 0.75
      const compressor = ctx.createDynamicsCompressor()
      compressor.threshold.value = -16
      compressor.knee.value = 22
      compressor.ratio.value = 4
      compressor.attack.value = 0.005
      compressor.release.value = 0.25
      this.master.connect(compressor)
      compressor.connect(ctx.destination)

      this.sfxBus = ctx.createGain()
      this.sfxBus.gain.value = 0.9
      this.sfxBus.connect(this.master)

      this.musicBus = ctx.createGain()
      this.musicBus.gain.value = 0
      this.musicBus.connect(this.master)

      // Shared noise buffer
      const length = ctx.sampleRate * 2
      const buffer = ctx.createBuffer(1, length, ctx.sampleRate)
      const data = buffer.getChannelData(0)
      for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
      this.noiseBuffer = buffer

      this.buildEngine()
      this.buildTyre()
      this.buildWind()
      this.ready = true
    } catch (error) {
      console.warn('Audio unavailable', error)
    }
  }

  noiseSource(loop = true) {
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    src.loop = loop
    return src
  }

  buildEngine() {
    const ctx = this.ctx
    this.engineGain = ctx.createGain()
    this.engineGain.gain.value = 0
    this.engineFilter = ctx.createBiquadFilter()
    this.engineFilter.type = 'lowpass'
    this.engineFilter.frequency.value = 420
    this.engineFilter.Q.value = 5.5
    this.engineFilter.connect(this.engineGain)
    this.engineGain.connect(this.sfxBus)

    this.engineOsc = []
    const specs = [
      { type: 'sawtooth', ratio: 1, gain: 0.5 },
      { type: 'sawtooth', ratio: 1.005, gain: 0.36 },
      { type: 'square', ratio: 0.5, gain: 0.34 },
      { type: 'sawtooth', ratio: 2.01, gain: 0.14 },
    ]
    for (const spec of specs) {
      const osc = ctx.createOscillator()
      osc.type = spec.type
      osc.frequency.value = 55
      const gain = ctx.createGain()
      gain.gain.value = spec.gain
      osc.connect(gain)
      gain.connect(this.engineFilter)
      osc.start()
      this.engineOsc.push({ osc, ratio: spec.ratio })
    }

    // A second, brighter layer that opens up under load.
    this.engineWhineGain = ctx.createGain()
    this.engineWhineGain.gain.value = 0
    this.engineWhineFilter = ctx.createBiquadFilter()
    this.engineWhineFilter.type = 'bandpass'
    this.engineWhineFilter.frequency.value = 1200
    this.engineWhineFilter.Q.value = 2
    const whine = ctx.createOscillator()
    whine.type = 'triangle'
    whine.frequency.value = 220
    whine.connect(this.engineWhineFilter)
    this.engineWhineFilter.connect(this.engineWhineGain)
    this.engineWhineGain.connect(this.sfxBus)
    whine.start()
    this.engineWhine = whine
  }

  buildTyre() {
    const ctx = this.ctx
    this.tyreGain = ctx.createGain()
    this.tyreGain.gain.value = 0
    this.tyreFilter = ctx.createBiquadFilter()
    this.tyreFilter.type = 'bandpass'
    this.tyreFilter.frequency.value = 1650
    this.tyreFilter.Q.value = 2.4
    const src = this.noiseSource()
    src.connect(this.tyreFilter)
    this.tyreFilter.connect(this.tyreGain)
    this.tyreGain.connect(this.sfxBus)
    src.start()
    this.tyreSrc = src
  }

  buildWind() {
    const ctx = this.ctx
    this.windGain = ctx.createGain()
    this.windGain.gain.value = 0
    this.windFilter = ctx.createBiquadFilter()
    this.windFilter.type = 'highpass'
    this.windFilter.frequency.value = 600
    const src = this.noiseSource()
    src.connect(this.windFilter)
    this.windFilter.connect(this.windGain)
    this.windGain.connect(this.sfxBus)
    src.start()
    this.windSrc = src
  }

  setMuted(muted) {
    this.muted = muted
    if (!this.ctx) return
    this.master.gain.setTargetAtTime(muted ? 0 : 0.75, this.ctx.currentTime, 0.05)
  }

  setEngine(speedNorm, throttle, boosting, drifting) {
    if (!this.ready) return
    const ctx = this.ctx
    const now = ctx.currentTime
    this.speedNorm = speedNorm
    const rpm = 0.12 + speedNorm * 0.88 + throttle * 0.1
    const base = 44 + rpm * 118
    for (const { osc, ratio } of this.engineOsc) {
      osc.frequency.setTargetAtTime(base * ratio, now, 0.055)
    }
    this.engineWhine.frequency.setTargetAtTime(base * 3.1, now, 0.06)
    this.engineFilter.frequency.setTargetAtTime(
      320 + rpm * 1500 + (boosting ? 900 : 0),
      now,
      0.08,
    )
    this.engineGain.gain.setTargetAtTime(
      0.05 + throttle * 0.07 + speedNorm * 0.05 + (boosting ? 0.035 : 0),
      now,
      0.08,
    )
    this.engineWhineGain.gain.setTargetAtTime(
      0.006 + throttle * 0.012 + (boosting ? 0.02 : 0),
      now,
      0.1,
    )
    this.windGain.gain.setTargetAtTime(speedNorm * speedNorm * 0.11, now, 0.15)
    this.setDrift(drifting)
  }

  setDrift(amount) {
    if (!this.ready) return
    this.driftAmount = amount
    const now = this.ctx.currentTime
    this.tyreGain.gain.setTargetAtTime(amount * 0.13, now, 0.06)
    this.tyreFilter.frequency.setTargetAtTime(1300 + amount * 900, now, 0.08)
  }

  // ---------- one-shots ----------

  blip(freq, duration, type = 'sine', gain = 0.12, slide = 0) {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + duration)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + 0.01)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    osc.connect(g)
    g.connect(this.sfxBus)
    osc.start(t)
    osc.stop(t + duration + 0.02)
  }

  ui() {
    this.blip(880, 0.07, 'triangle', 0.06, 220)
  }

  pickup(step = 0) {
    const base = 660 * Math.pow(1.122, Math.min(step, 8))
    this.blip(base, 0.12, 'sine', 0.1, 260)
    setTimeout(() => this.blip(base * 1.5, 0.14, 'triangle', 0.07, 180), 55)
  }

  checkpoint() {
    if (!this.ready) return
    const notes = [523.25, 659.25, 783.99, 1046.5]
    notes.forEach((freq, i) => {
      setTimeout(() => this.blip(freq, 0.28, 'triangle', 0.1, 60), i * 70)
    })
  }

  nearMiss() {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const src = this.noiseSource(false)
    const filter = ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.setValueAtTime(400, t)
    filter.frequency.exponentialRampToValueAtTime(3200, t + 0.28)
    filter.Q.value = 2.2
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.12, t + 0.04)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.34)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.sfxBus)
    src.start(t)
    src.stop(t + 0.4)
  }

  impact(strength = 0.5) {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const src = this.noiseSource(false)
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.setValueAtTime(1800, t)
    filter.frequency.exponentialRampToValueAtTime(180, t + 0.3)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.28 * strength + 0.05, t + 0.008)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.42)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.sfxBus)
    src.start(t)
    src.stop(t + 0.45)

    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(120, t)
    osc.frequency.exponentialRampToValueAtTime(38, t + 0.22)
    const og = ctx.createGain()
    og.gain.setValueAtTime(0.0001, t)
    og.gain.exponentialRampToValueAtTime(0.24 * strength + 0.04, t + 0.01)
    og.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
    osc.connect(og)
    og.connect(this.sfxBus)
    osc.start(t)
    osc.stop(t + 0.32)
  }

  boost() {
    if (!this.ready) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = 'sawtooth'
    osc.frequency.setValueAtTime(110, t)
    osc.frequency.exponentialRampToValueAtTime(520, t + 0.55)
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.setValueAtTime(500, t)
    filter.frequency.exponentialRampToValueAtTime(4200, t + 0.5)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(0.09, t + 0.06)
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.7)
    osc.connect(filter)
    filter.connect(g)
    g.connect(this.sfxBus)
    osc.start(t)
    osc.stop(t + 0.75)
  }

  countdown(go = false) {
    this.blip(go ? 880 : 440, go ? 0.5 : 0.12, 'square', go ? 0.1 : 0.05)
  }

  // ---------- music ----------

  note(freq, time, duration, type, gain, filterFreq, detune = 0) {
    const ctx = this.ctx
    const osc = ctx.createOscillator()
    osc.type = type
    osc.frequency.value = freq
    osc.detune.value = detune
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.setValueAtTime(filterFreq, time)
    filter.frequency.exponentialRampToValueAtTime(Math.max(120, filterFreq * 0.4), time + duration)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, time)
    g.gain.exponentialRampToValueAtTime(gain, time + Math.min(0.08, duration * 0.3))
    g.gain.exponentialRampToValueAtTime(0.0001, time + duration)
    osc.connect(filter)
    filter.connect(g)
    g.connect(this.musicBus)
    osc.start(time)
    osc.stop(time + duration + 0.03)
  }

  kick(time) {
    const ctx = this.ctx
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(140, time)
    osc.frequency.exponentialRampToValueAtTime(42, time + 0.16)
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, time)
    g.gain.exponentialRampToValueAtTime(0.5, time + 0.005)
    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.24)
    osc.connect(g)
    g.connect(this.musicBus)
    osc.start(time)
    osc.stop(time + 0.26)
  }

  snare(time) {
    const ctx = this.ctx
    const src = this.noiseSource(false)
    const filter = ctx.createBiquadFilter()
    filter.type = 'bandpass'
    filter.frequency.value = 2100
    filter.Q.value = 1.2
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, time)
    g.gain.exponentialRampToValueAtTime(0.22, time + 0.005)
    g.gain.exponentialRampToValueAtTime(0.0001, time + 0.18)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.musicBus)
    src.start(time)
    src.stop(time + 0.2)
  }

  hat(time, open = false) {
    const ctx = this.ctx
    const src = this.noiseSource(false)
    const filter = ctx.createBiquadFilter()
    filter.type = 'highpass'
    filter.frequency.value = 7200
    const g = ctx.createGain()
    const dur = open ? 0.12 : 0.04
    g.gain.setValueAtTime(0.0001, time)
    g.gain.exponentialRampToValueAtTime(0.09, time + 0.004)
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.musicBus)
    src.start(time)
    src.stop(time + dur + 0.02)
  }

  scheduleBar(bar, time) {
    const stepDur = 0.125
    const chords = [
      { root: 110.0, notes: [220.0, 261.63, 329.63] }, // Am
      { root: 87.31, notes: [174.61, 220.0, 261.63] }, // F
      { root: 130.81, notes: [261.63, 329.63, 392.0] }, // C
      { root: 98.0, notes: [196.0, 246.94, 293.66] }, // G
    ]
    const chord = chords[bar % 4]
    const barStart = time

    // pad
    for (const noteFreq of chord.notes) {
      this.note(noteFreq, barStart, 1.9, 'sawtooth', 0.022, 900, -7)
      this.note(noteFreq * 1.004, barStart, 1.9, 'triangle', 0.018, 1200, 6)
    }

    // bass
    const bassSteps = [0, 3, 6, 8, 11, 14]
    for (const s of bassSteps) {
      const accent = s === 0 || s === 8 ? 1 : 0.65
      this.note(chord.root, barStart + s * stepDur, 0.19, 'sawtooth', 0.11 * accent, 520)
      this.note(chord.root / 2, barStart + s * stepDur, 0.2, 'sine', 0.12 * accent, 300)
    }

    // arpeggio
    const arp = [0, 1, 2, 1, 2, 0, 1, 2]
    for (let s = 0; s < 16; s += 2) {
      const noteFreq = chord.notes[arp[(s / 2) % arp.length]] * 2
      if ((s + bar) % 4 === 0) continue
      this.note(noteFreq, barStart + s * stepDur, 0.14, 'square', 0.022, 2400)
    }

    // drums
    for (let s = 0; s < 16; s++) {
      const t = barStart + s * stepDur
      if (s % 4 === 0) this.kick(t)
      if (s === 4 || s === 12) this.snare(t)
      if (s % 2 === 1) this.hat(t, s === 14)
    }
  }

  startMusic() {
    if (!this.ready || this.musicPlaying) return
    this.musicPlaying = true
    this.step = 0
    const ctx = this.ctx
    this.nextNoteTime = ctx.currentTime + 0.12
    this.musicBus.gain.setTargetAtTime(0.9, ctx.currentTime, 0.6)
    this.timer = setInterval(() => {
      if (!this.musicPlaying) return
      const ahead = ctx.currentTime + 0.3
      while (this.nextNoteTime < ahead) {
        this.scheduleBar(this.step, this.nextNoteTime)
        this.nextNoteTime += 2.0
        this.step++
      }
    }, 120)
  }

  stopMusic(fade = true) {
    this.musicPlaying = false
    if (this.timer) clearInterval(this.timer)
    this.timer = null
    if (this.ctx) {
      this.musicBus.gain.setTargetAtTime(0, this.ctx.currentTime, fade ? 0.4 : 0.01)
    }
  }

  suspend() {
    this.ctx?.suspend?.().catch(() => {})
  }

  resume() {
    this.ctx?.resume?.().catch(() => {})
  }
}

import { clamp, damp } from './utils.js'

/**
 * Unified input: multi-touch pads, keyboard, gamepad and optional tilt.
 */
export class Controls {
  constructor(root, { onPause, onReset } = {}) {
    this.root = root
    this.onPause = onPause
    this.onReset = onReset

    this.keys = new Set()
    this.touch = { left: false, right: false, gas: false, brake: false, drift: false, boost: false }
    this.pointers = new Map()

    this.tiltEnabled = false
    this.tiltAvailable = false
    this.tiltNeutral = null
    this.tiltValue = 0
    this.tiltRaw = 0
    this.orientationHandler = null

    this.steer = 0
    this.steerTarget = 0
    this.boostWasDown = false
    this.gamepadIndex = null

    this.state = {
      steer: 0,
      throttle: 0,
      brake: 0,
      handbrake: false,
      boost: false,
      boostPressed: false,
      tiltActive: false,
    }

    this.bindButtons()
    this.bindKeyboard()
    this.bindGamepad()
    this.bindPointerFallback()
  }

  bindButtons() {
    const buttons = this.root.querySelectorAll('[data-action]')
    buttons.forEach((button) => {
      const action = button.dataset.action
      const down = (event) => {
        event.preventDefault()
        if (event.pointerId !== undefined) {
          this.pointers.set(event.pointerId, { action, button })
          try {
            button.setPointerCapture(event.pointerId)
          } catch {}
        }
        this.setTouch(action, true)
        button.classList.add('is-down')
        if (action === 'boost') this.boostWasDown = true
        if (navigator.vibrate) navigator.vibrate(8)
      }
      const up = (event) => {
        event.preventDefault()
        if (event.pointerId !== undefined) this.pointers.delete(event.pointerId)
        this.setTouch(action, false)
        button.classList.remove('is-down')
      }
      button.addEventListener('pointerdown', down)
      button.addEventListener('pointerup', up)
      button.addEventListener('pointercancel', up)
      button.addEventListener('lostpointercapture', up)
      button.addEventListener('contextmenu', (e) => e.preventDefault())
    })
  }

  bindPointerFallback() {
    window.addEventListener('pointerup', (event) => {
      const entry = this.pointers.get(event.pointerId)
      if (!entry) return
      this.pointers.delete(event.pointerId)
      this.setTouch(entry.action, false)
      entry.button.classList.remove('is-down')
    })
    window.addEventListener('blur', () => this.releaseAll())
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.releaseAll()
    })
  }

  bindKeyboard() {
    window.addEventListener('keydown', (event) => {
      const code = event.code
      if (
        ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(code) &&
        !event.target.closest?.('input, textarea')
      ) {
        event.preventDefault()
      }
      if (event.repeat) return
      this.keys.add(code)
      if (code === 'Space') this.boostWasDown = this.boostWasDown || false
      if (code === 'KeyP' || code === 'Escape') this.onPause?.()
      if (code === 'KeyR') this.onReset?.()
      if (code === 'ShiftLeft' || code === 'ShiftRight') this.boostWasDown = true
    })
    window.addEventListener('keyup', (event) => this.keys.delete(event.code))
  }

  bindGamepad() {
    window.addEventListener('gamepadconnected', (event) => {
      this.gamepadIndex = event.gamepad.index
    })
    window.addEventListener('gamepaddisconnected', () => {
      this.gamepadIndex = null
    })
  }

  setTouch(action, value) {
    if (!(action in this.touch)) return
    this.touch[action] = value
    if (action === 'boost' && value) this.boostWasDown = true
  }

  releaseAll() {
    for (const key of Object.keys(this.touch)) this.touch[key] = false
    this.pointers.clear()
    this.keys.clear()
    this.root.querySelectorAll('.ctrl-btn.is-down').forEach((b) => b.classList.remove('is-down'))
  }

  async enableTilt() {
    if (typeof DeviceOrientationEvent === 'undefined') return false
    try {
      if (typeof DeviceOrientationEvent.requestPermission === 'function') {
        const permission = await DeviceOrientationEvent.requestPermission()
        if (permission !== 'granted') return false
      }
      if (!this.orientationHandler) {
        this.orientationHandler = (event) => this.onOrientation(event)
        window.addEventListener('deviceorientation', this.orientationHandler, true)
      }
      this.tiltEnabled = true
      this.tiltNeutral = null
      this.tiltAvailable = true
      return true
    } catch {
      return false
    }
  }

  disableTilt() {
    this.tiltEnabled = false
    this.tiltValue = 0
    this.tiltRaw = 0
    if (this.orientationHandler) {
      window.removeEventListener('deviceorientation', this.orientationHandler, true)
      this.orientationHandler = null
    }
  }

  onOrientation(event) {
    if (!this.tiltEnabled) return
    const angle =
      (screen.orientation && screen.orientation.angle) ||
      (typeof window.orientation === 'number' ? window.orientation : 0)
    let value
    if (Math.abs(angle) === 90) {
      value = -event.beta * Math.sign(angle)
    } else {
      value = event.gamma
    }
    if (value == null || Number.isNaN(value)) return
    this.tiltRaw = value
    if (this.tiltNeutral === null) this.tiltNeutral = value
    const deadzone = 1.5
    const delta = value - this.tiltNeutral
    const effective = Math.abs(delta) < deadzone ? 0 : delta - Math.sign(delta) * deadzone
    this.tiltValue = clamp(effective / 20, -1, 1)
    // Slowly re-centre so the player can hold a natural angle.
    this.tiltNeutral = damp(this.tiltNeutral, value, 0.12, 1 / 60)
  }

  recalibrateTilt() {
    this.tiltNeutral = this.tiltRaw || null
  }

  pollGamepad() {
    if (this.gamepadIndex === null || !navigator.getGamepads) return null
    const pad = navigator.getGamepads()[this.gamepadIndex]
    if (!pad) return null
    const axis = pad.axes[0] || 0
    const steer = Math.abs(axis) > 0.12 ? axis : 0
    const throttle = pad.buttons[7]?.value || 0
    const brake = pad.buttons[6]?.value || 0
    const drift = pad.buttons[0]?.pressed || false
    const boost = pad.buttons[1]?.pressed || false
    return { steer, throttle, brake, drift, boost }
  }

  update(dt) {
    const pad = this.pollGamepad()

    let target = 0
    if (this.touch.left) target -= 1
    if (this.touch.right) target += 1
    const keyLeft = this.keys.has('ArrowLeft') || this.keys.has('KeyA')
    const keyRight = this.keys.has('ArrowRight') || this.keys.has('KeyD')
    if (keyLeft) target -= 1
    if (keyRight) target += 1

    if (target === 0 && this.tiltEnabled && this.tiltAvailable) {
      target = this.tiltValue
    }
    if (pad && Math.abs(pad.steer) > 0.01) target = pad.steer
    target = clamp(target, -1, 1)

    // Nonlinear steering response near centre for stability.
    const shaped = Math.sign(target) * Math.pow(Math.abs(target), 1.25)
    this.steerTarget = shaped
    const rate = Math.abs(shaped) > 0.02 ? 6.5 : 9
    this.steer = damp(this.steer, shaped, rate, dt)

    const gasKey = this.keys.has('ArrowUp') || this.keys.has('KeyW')
    const brakeKey = this.keys.has('ArrowDown') || this.keys.has('KeyS')
    const driftKey = this.keys.has('Space')
    const boostKey = this.keys.has('ShiftLeft') || this.keys.has('ShiftRight')

    const throttle = clamp((this.touch.gas ? 1 : 0) + (pad?.throttle || 0) + (gasKey ? 1 : 0), 0, 1)
    const brake = clamp((this.touch.brake ? 1 : 0) + (pad?.brake || 0) + (brakeKey ? 1 : 0), 0, 1)
    const handbrake = this.touch.drift || driftKey || pad?.drift || false
    const boost = this.touch.boost || boostKey || pad?.boost || false

    this.state.steer = this.steer
    this.state.throttle = throttle
    this.state.brake = brake
    this.state.handbrake = handbrake
    this.state.boost = boost
    this.state.boostPressed = this.boostWasDown
    this.state.tiltActive = this.tiltEnabled && this.tiltAvailable
    this.boostWasDown = false
    return this.state
  }
}

import * as THREE from 'three'
import { clamp, rand } from './utils.js'
import { makeGlowTexture, makeSmokeTexture } from './textures.js'

const particleVertex = /* glsl */ `
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  varying float vAlpha;
  varying vec3 vColor;
  uniform float uScale;
  void main() {
    vAlpha = aAlpha;
    vColor = aColor;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = clamp(aSize * uScale / max(0.001, -mv.z), 0.0, 190.0);
    gl_Position = projectionMatrix * mv;
  }
`

const particleFragment = /* glsl */ `
  uniform sampler2D uTexture;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vec4 tex = texture2D(uTexture, gl_PointCoord);
    float a = tex.a * vAlpha;
    if (a < 0.004) discard;
    gl_FragColor = vec4(vColor, a);
  }
`

export class Particles {
  constructor(scene, { max = 400, additive = true, texture = null } = {}) {
    this.max = max
    this.scene = scene
    this.particles = []
    this.cursor = 0
    this.scale = 600

    const geometry = new THREE.BufferGeometry()
    this.positions = new Float32Array(max * 3)
    this.colors = new Float32Array(max * 3)
    this.sizes = new Float32Array(max)
    this.alphas = new Float32Array(max)
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geometry.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3))
    geometry.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1))
    geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1))
    geometry.setDrawRange(0, max)

    const map = texture || (additive ? makeGlowTexture(64) : makeSmokeTexture(128))
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTexture: { value: map },
        uScale: { value: this.scale },
      },
      vertexShader: particleVertex,
      fragmentShader: particleFragment,
      transparent: true,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    })

    this.points = new THREE.Points(geometry, material)
    this.points.frustumCulled = false
    this.points.renderOrder = additive ? 4 : 3
    scene.add(this.points)
    this.geometry = geometry
    this.material = material
    this.additive = additive
  }

  spawn(options) {
    const {
      x = 0,
      y = 0,
      z = 0,
      vx = 0,
      vy = 0,
      vz = 0,
      life = 1,
      size0 = 0.4,
      size1 = 1.2,
      color = 0xffffff,
      alpha = 1,
      gravity = 0,
      drag = 0,
      fadeIn = 0.06,
      additive = this.additive,
    } = options
    if (this.particles.length < this.max) {
      const particle = {
        x, y, z, vx, vy, vz,
        life, maxLife: life,
        size0, size1,
        color: new THREE.Color(color),
        alpha, gravity, drag, fadeIn, additive,
      }
      this.particles.push(particle)
      return particle
    }
    // recycle the oldest
    const particle = this.particles[this.cursor]
    this.cursor = (this.cursor + 1) % this.max
    Object.assign(particle, {
      x, y, z, vx, vy, vz,
      life, maxLife: life,
      size0, size1,
      alpha, gravity, drag, fadeIn,
    })
    particle.color.set(color)
    return particle
  }

  burst(position, { count = 12, color = 0x4df3ff, speed = 8, size = 0.5, life = 0.7, gravity = -6, spread = 1 } = {}) {
    for (let i = 0; i < count; i++) {
      const theta = Math.random() * Math.PI * 2
      const phi = Math.acos(rand(-1, 1))
      const s = speed * rand(0.35, 1)
      this.spawn({
        x: position.x + rand(-0.2, 0.2),
        y: position.y + rand(-0.1, 0.3),
        z: position.z + rand(-0.2, 0.2),
        vx: Math.sin(phi) * Math.cos(theta) * s * spread,
        vy: Math.abs(Math.cos(phi)) * s * 0.7,
        vz: Math.sin(phi) * Math.sin(theta) * s * spread,
        life: life * rand(0.6, 1.2),
        size0: size * rand(0.5, 1.1),
        size1: size * 0.15,
        color,
        alpha: 1,
        gravity,
        drag: 1.6,
      })
    }
  }

  smoke(position, { size = 1.2, life = 1.8, color = 0x8d97ad, alpha = 0.34, vx = 0, vy = 0.4, vz = 0, growth = 2.4 } = {}) {
    this.spawn({
      x: position.x + rand(-0.15, 0.15),
      y: position.y + rand(0, 0.25),
      z: position.z + rand(-0.15, 0.15),
      vx: vx + rand(-0.4, 0.4),
      vy: vy + rand(0.1, 0.5),
      vz: vz + rand(-0.4, 0.4),
      life: life * rand(0.75, 1.25),
      size0: size * rand(0.7, 1.2),
      size1: size * growth,
      color,
      alpha,
      gravity: 0.35,
      drag: 1.4,
      fadeIn: 0.12,
    })
  }

  update(dt, camera) {
    const positions = this.positions
    const colors = this.colors
    const sizes = this.sizes
    const alphas = this.alphas
    let alive = 0

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i]
      p.life -= dt
      if (p.life <= 0) {
        this.particles.splice(i, 1)
        continue
      }
      const drag = Math.exp(-p.drag * dt)
      p.vx *= drag
      p.vz *= drag
      p.vy = p.vy * drag + p.gravity * dt
      p.x += p.vx * dt
      p.y += p.vy * dt
      p.z += p.vz * dt
      if (p.y < 0.03) {
        p.y = 0.03
        p.vy *= -0.25
      }
      alive++
    }

    for (let i = 0; i < this.particles.length; i++) {
      const p = this.particles[i]
      const t = 1 - p.life / p.maxLife
      const fade = Math.min(1, t / Math.max(0.001, p.fadeIn))
      positions[i * 3] = p.x
      positions[i * 3 + 1] = p.y
      positions[i * 3 + 2] = p.z
      colors[i * 3] = p.color.r
      colors[i * 3 + 1] = p.color.g
      colors[i * 3 + 2] = p.color.b
      sizes[i] = p.size0 + (p.size1 - p.size0) * t
      alphas[i] = p.alpha * fade * Math.pow(1 - t, p.additive ? 0.7 : 0.45)
    }

    for (let i = this.particles.length; i < this.max; i++) {
      alphas[i] = 0
    }

    if (camera) {
      const scale =
        (this.scene.userData.viewportHeight || 800) /
        (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov) / 2))
      this.material.uniforms.uScale.value = scale
    }

    this.geometry.attributes.position.needsUpdate = true
    this.geometry.attributes.aColor.needsUpdate = true
    this.geometry.attributes.aSize.needsUpdate = true
    this.geometry.attributes.aAlpha.needsUpdate = true
    this.alive = alive
  }

  clear() {
    this.particles.length = 0
    this.alphas.fill(0)
    this.geometry.attributes.aAlpha.needsUpdate = true
  }
}

const skidVertex = /* glsl */ `
  attribute float aAlpha;
  attribute float aBirth;
  uniform float uTime;
  varying float vAlpha;
  void main() {
    float age = uTime - aBirth;
    vAlpha = aAlpha * clamp(1.0 - age / 16.0, 0.0, 1.0);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`

const skidFragment = /* glsl */ `
  varying float vAlpha;
  uniform vec3 uColor;
  void main() {
    if (vAlpha < 0.003) discard;
    gl_FragColor = vec4(uColor, vAlpha);
  }
`

export class SkidMarks {
  constructor(scene, max = 900) {
    this.max = max
    this.cursor = 0
    this.time = 0
    this.last = new Map()

    const geometry = new THREE.BufferGeometry()
    this.positions = new Float32Array(max * 4 * 3)
    this.alphas = new Float32Array(max * 4)
    this.births = new Float32Array(max * 4)
    const indices = new Uint32Array(max * 6)
    for (let i = 0; i < max; i++) {
      const v = i * 4
      indices[i * 6] = v
      indices[i * 6 + 1] = v + 1
      indices[i * 6 + 2] = v + 2
      indices[i * 6 + 3] = v + 1
      indices[i * 6 + 4] = v + 3
      indices[i * 6 + 5] = v + 2
    }
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geometry.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1))
    geometry.setAttribute('aBirth', new THREE.BufferAttribute(this.births, 1))
    geometry.setIndex(new THREE.BufferAttribute(indices, 1))

    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColor: { value: new THREE.Color(0x05060a) },
      },
      vertexShader: skidVertex,
      fragmentShader: skidFragment,
      transparent: true,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
    })

    this.mesh = new THREE.Mesh(geometry, material)
    this.mesh.frustumCulled = false
    this.mesh.renderOrder = 2
    scene.add(this.mesh)
    this.geometry = geometry
    this.material = material
  }

  reset() {
    this.alphas.fill(0)
    this.births.fill(0)
    this.geometry.attributes.aAlpha.needsUpdate = true
    this.geometry.attributes.aBirth.needsUpdate = true
    this.last.clear()
    this.cursor = 0
  }

  add(key, x, z, headingX, headingZ, width = 0.3, strength = 1) {
    const previous = this.last.get(key)
    if (!previous) {
      this.last.set(key, { x, z })
      return
    }
    const dx = x - previous.x
    const dz = z - previous.z
    const distance = Math.hypot(dx, dz)
    if (distance < 0.18) return
    if (distance > 4) {
      previous.x = x
      previous.z = z
      return
    }

    // perpendicular to direction of travel
    const len = Math.max(0.0001, Math.hypot(dx, dz))
    const px = (-dz / len) * width * 0.5
    const pz = (dx / len) * width * 0.5
    const y = 0.018
    const i = this.cursor
    this.cursor = (this.cursor + 1) % this.max
    const v = i * 4
    const p = this.positions
    p[v * 3] = previous.x + px
    p[v * 3 + 1] = y
    p[v * 3 + 2] = previous.z + pz
    p[v * 3 + 3] = previous.x - px
    p[v * 3 + 4] = y
    p[v * 3 + 5] = previous.z - pz
    p[v * 3 + 6] = x + px
    p[v * 3 + 7] = y
    p[v * 3 + 8] = x + pz * 0 + pz
    p[v * 3 + 6] = x + px
    p[v * 3 + 7] = y
    p[v * 3 + 8] = z + pz
    p[v * 3 + 9] = x - px
    p[v * 3 + 10] = y
    p[v * 3 + 11] = z - pz

    const alpha = clamp(0.5 * strength, 0.06, 0.75)
    for (let k = 0; k < 4; k++) {
      this.alphas[v + k] = alpha
      this.births[v + k] = this.time
    }
    this.geometry.attributes.position.needsUpdate = true
    this.geometry.attributes.aAlpha.needsUpdate = true
    this.geometry.attributes.aBirth.needsUpdate = true
    previous.x = x
    previous.z = z
  }

  update(dt) {
    this.time += dt
    this.material.uniforms.uTime.value = this.time
  }
}

export class Rain {
  constructor(scene, count = 900) {
    this.count = count
    this.positions = new Float32Array(count * 2 * 3)
    this.drops = []
    this.area = 80
    this.height = 38
    for (let i = 0; i < count; i++) {
      this.drops.push({
        x: rand(-this.area / 2, this.area / 2),
        y: rand(0, this.height),
        z: rand(-this.area / 2, this.area / 2),
        speed: rand(28, 46),
        len: rand(0.5, 1.4),
      })
    }
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    const material = new THREE.LineBasicMaterial({
      color: 0x9fd6ff,
      transparent: true,
      opacity: 0.3,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      fog: false,
    })
    this.mesh = new THREE.LineSegments(geometry, material)
    this.mesh.frustumCulled = false
    this.mesh.renderOrder = 5
    scene.add(this.mesh)
    this.geometry = geometry
    this.material = material
  }

  setEnabled(enabled) {
    this.mesh.visible = enabled
  }

  update(dt, camera, speed = 0) {
    if (!this.mesh.visible) return
    const center = camera.position
    const half = this.area / 2
    const wind = -2.5
    for (let i = 0; i < this.count; i++) {
      const drop = this.drops[i]
      drop.y -= drop.speed * dt
      drop.x += wind * dt
      if (drop.y < center.y - 6) {
        drop.y += this.height
        drop.x = center.x + rand(-half, half)
        drop.z = center.z + rand(-half, half)
      }
      // wrap horizontally around the camera
      if (drop.x < center.x - half) drop.x += this.area
      if (drop.x > center.x + half) drop.x -= this.area
      if (drop.z < center.z - half) drop.z += this.area
      if (drop.z > center.z + half) drop.z -= this.area

      const p = this.positions
      const v = i * 6
      const len = drop.len * (1 + speed * 0.02)
      p[v] = drop.x
      p[v + 1] = drop.y
      p[v + 2] = drop.z
      p[v + 3] = drop.x - wind * 0.04
      p[v + 4] = drop.y + len
      p[v + 5] = drop.z
    }
    this.geometry.attributes.position.needsUpdate = true
  }
}

