    })
    const carbon = new THREE.MeshStandardMaterial({
      color: 0x0a0c12,
      metalness: 0.62,
      roughness: 0.38,
      envMapIntensity: 1.2,
    })
    const glass = new THREE.MeshPhysicalMaterial({
      color: 0x07161f,
      metalness: 0.92,
