  reset(x, z, heading = 0) {
    this.pos.set(x, z)
    this.vel.set(0, 0)
    this.heading = heading
    this.yawRate = 0
    this.slip = 0
    this.driftIntensity = 0
    this.speed = 0
    this.forwardSpeed = 0
    this.steerVisual = 0
    this.wheelSpin = 0
    this.shake = 0
    this.pendingImpact = 0
    this.impactCooldown = 0
    this.boosting = false
    this.boostFlame = 0
    this.tiltRoll = 0
    this.tiltPitch = 0
    this.root.position.set(x, 0, z)
    this.root.rotation.set(0, heading, 0)
    this.bodyPivot.rotation.set(0, 0, 0)
    this.bodyPivot.position.set(0, 0, 0)
    this.tailMaterial.emissiveIntensity = 2.2
    this.underglow.material.opacity = 0.28
    this.headlight.intensity = 180
    this.flames.forEach((flame) => (flame.material.opacity = 0))
    this.updateWheelWorld()
  }

  step(h, input, city) {
    const forward = _forward.set(Math.sin(this.heading), Math.cos(this.heading))
    const right = _right.set(Math.cos(this.heading), -Math.sin(this.heading))

    let vf = this.vel.dot(forward)
    let vl = this.vel.dot(right)

    const boost = input.boost
    const maxSpeed = boost ? BOOST_SPEED : MAX_SPEED
    const throttle = input.throttle
    const brake = input.brake

    if (throttle > 0) {
      const rate = boost ? 1.35 : 0.66
      vf += (maxSpeed - vf) * rate * throttle * h
    }
    if (brake > 0) {
      if (vf > 0.4) {
        vf = Math.max(0, vf - 36 * brake * h)
      } else {
        vf = Math.max(-11, vf - 13 * brake * h)
      }
    }
    if (throttle <= 0 && brake <= 0) {
      vf *= Math.exp(-0.42 * h)
    }

    // steering authority falls away at very high speed
    const absVf = Math.abs(vf)
    const authority =
      clamp(absVf / 4.5, 0, 1) * (1 - 0.48 * clamp(absVf / 82, 0, 1))
    const driftMul = input.handbrake ? 1.42 : 1
    const yawRate = input.steer * 2.2 * authority * driftMul
    this.yawRate = yawRate

    // Lateral grip: handbrake lets the rear step out.
    let grip = input.handbrake ? 1.35 : 9.4
    grip += clamp(1 - absVf / 6, 0, 1) * 6
    const vlNew = vl * Math.exp(-grip * h)
    const removed = vl - vlNew
    vf += Math.abs(removed) * 0.12
    vl = vlNew

    if (input.handbrake) vf *= Math.exp(-0.42 * h)
    vf = clamp(vf, -12, maxSpeed + 2)

    // off-road penalty
    const onRoad = city.isOnRoad(this.pos.x, this.pos.y)
    this.offRoad = !onRoad && Math.abs(vf) > 2
    if (!onRoad) vf *= Math.exp(-0.85 * h)

    // recompose velocity in the current heading frame, then rotate the car
    this.vel.set(forward.x * vf + right.x * vl, forward.y * vf + right.y * vl)
    this.heading += yawRate * h

    this.pos.x += this.vel.x * h
    this.pos.y += this.vel.y * h

    // building collision
    const hit = city.collide(this.pos.x, this.pos.y, 1.02)
    if (hit) {
      this.pos.x += hit.nx * (hit.depth + 0.03)
      this.pos.y += hit.nz * (hit.depth + 0.03)
      const vn = this.vel.x * hit.nx + this.vel.y * hit.nz
      if (vn < 0) {
        this.vel.x -= hit.nx * vn * 1.25
        this.vel.y -= hit.nz * vn * 1.25
      }
      const strength = clamp(-vn / 24, 0.2, 1)
      this.vel.multiplyScalar(0.55)
      if (this.impactCooldown <= 0) {
        this.impactCooldown = 0.4
        this.pendingImpact = strength
        this.shake = Math.max(this.shake, strength)
        this.impactFlash = strength
      }
    }

    this.speed = this.vel.length()
    this.forwardSpeed = vf
    this.slip = Math.atan2(vl, Math.max(1.2, Math.abs(vf)))
    const drift =
      this.speed > 7
        ? clamp((Math.abs(this.slip) - 0.1) / 0.55, 0, 1) *
          clamp(this.speed / 18, 0, 1)
        : 0
    this.driftIntensity = drift
    this.boosting = boost && this.speed > 1
  }

  update(dt, input, city, effects) {
    this.time += dt
    const steps = Math.min(5, Math.max(1, Math.ceil(dt / 0.016)))
    const h = dt / steps
    for (let i = 0; i < steps; i++) this.step(h, input, city)
    this.impactCooldown = Math.max(0, this.impactCooldown - dt)
    this.shake = damp(this.shake, 0, 5, dt)
    this.rumble = this.offRoad ? 1 : 0

    // ----- visual transform -----
    this.root.position.set(this.pos.x, 0, this.pos.y)
    this.root.rotation.y = this.heading

    this.accel = damp(this.accel, (this.forwardSpeed - this.lastForwardSpeed) / Math.max(0.001, dt), 8, dt)
    this.lastForwardSpeed = this.forwardSpeed

    const speedNorm = clamp(this.speed / MAX_SPEED, 0, 1.3)
    const targetRoll = clamp(this.yawRate * this.speed * 0.0017, -0.085, 0.085)
    const targetPitch = clamp(-this.accel * 0.0022, -0.045, 0.06)
    this.tiltRoll = damp(this.tiltRoll, targetRoll, 6, dt)
    this.tiltPitch = damp(this.tiltPitch, targetPitch, 7, dt)
    this.bodyPivot.rotation.z = this.tiltRoll
    this.bodyPivot.rotation.x = this.tiltPitch
    this.bodyPivot.position.y =
      0.012 * Math.sin(this.time * 11 + this.speed * 0.18) * speedNorm +
      0.006 * Math.sin(this.time * 31) * speedNorm

    // wheels
    this.wheelSpin += (this.forwardSpeed / WHEEL_RADIUS) * dt
    const steerTarget = input.steer * 0.52
    this.steerVisual = damp(this.steerVisual, steerTarget, 10, dt)
    for (const wheel of this.wheels) {
      wheel.spin.rotation.x = this.wheelSpin
      if (wheel.front) wheel.steerPivot.rotation.y = this.steerVisual
    }

    // lights
    this.braking = input.brake > 0.1 || input.handbrake
    this.tailMaterial.emissiveIntensity = damp(
      this.tailMaterial.emissiveIntensity,
      this.braking ? 7 : 2.2,
      14,
      dt,
    )
    this.underglow.material.opacity = 0.24 + (this.boosting ? 0.2 : 0) + this.driftIntensity * 0.1
    this.headlight.intensity = 180 + (this.boosting ? 40 : 0)
    this.underLight.intensity = 10 + this.driftIntensity * 8

    this.boostFlame = damp(this.boostFlame, this.boosting ? 1 : 0, 12, dt)
    for (const flame of this.flames) {
      flame.material.opacity = this.boostFlame * (0.65 + Math.random() * 0.3)
      const s = 0.75 + this.boostFlame * (0.4 + Math.random() * 0.35)
      flame.scale.set(s, s, 0.6 + this.boostFlame * 0.9)
    }

    this.updateWheelWorld()

    // effects
    if (effects) {
      if (this.driftIntensity > 0.12) {
        const count = Math.random() < this.driftIntensity ? 2 : 1
        for (let i = 0; i < count; i++) {
          const wheel = this.rearWheelWorld[i % 2]
          effects.smoke.spawn({
            x: wheel.x,
            y: 0.16,
            z: wheel.z,
            vx: -this.vel.x * 0.12 + (Math.random() - 0.5) * 1.4,
            vy: 0.4 + Math.random() * 0.5,
            vz: -this.vel.y * 0.12 + (Math.random() - 0.5) * 1.4,
            life: 1.2 + Math.random() * 0.9,
            size0: 0.5 + this.driftIntensity * 0.4,
            size1: 2.4 + this.driftIntensity * 1.6,
            color: 0xa8b4c8,
            alpha: 0.16 + this.driftIntensity * 0.18,
            gravity: 0.2,
            drag: 1.1,
            fadeIn: 0.12,
          })
        }
        effects.skids.add(
          'rl',
          this.rearWheelWorld[0].x,
          this.rearWheelWorld[0].z,
          0,
          0,
          0.34,
          this.driftIntensity,
        )
        effects.skids.add(
          'rr',
          this.rearWheelWorld[1].x,
          this.rearWheelWorld[1].z,
          0,
          0,
          0.34,
          this.driftIntensity,
        )
      } else {
        effects.skids.last.delete('rl')
        effects.skids.last.delete('rr')
      }

      if (this.boosting) {
        const back = _tmp.set(
          -Math.sin(this.heading) * 2.6,
          0.45,
          -Math.cos(this.heading) * 2.6,
        )
        effects.sparks.spawn({
          x: this.pos.x + back.x + (Math.random() - 0.5) * 0.5,
          y: back.y,
          z: this.pos.y + back.z + (Math.random() - 0.5) * 0.5,
          vx: -this.vel.x * 0.25 + (Math.random() - 0.5) * 1.5,
          vy: 0.2,
          vz: -this.vel.y * 0.25 + (Math.random() - 0.5) * 1.5,
          life: 0.35,
          size0: 0.7,
          size1: 0.1,
          color: Math.random() > 0.4 ? 0x6fe6ff : 0xff8a2b,
          alpha: 1,
          gravity: 0,
          drag: 3,
        })
      }
    }
  }

  updateWheelWorld() {
    const sin = Math.sin(this.heading)
    const cos = Math.cos(this.heading)
    const rear = [
      [-0.9, -1.42],
      [0.9, -1.42],
    ]
    const front = [
      [-0.9, 1.42],
      [0.9, 1.42],
    ]
    for (let i = 0; i < 2; i++) {
      const [lx, lz] = rear[i]
      this.rearWheelWorld[i].set(
        this.pos.x + lx * cos + lz * sin,
        0.02,
        this.pos.y - lx * sin + lz * cos,
      )
      const [fx, fz] = front[i]
      this.frontWheelWorld[i].set(
        this.pos.x + fx * cos + fz * sin,
        0.02,
        this.pos.y - fx * sin + fz * cos,
      )
    }
  }

  applyTrafficHit(strength, nx, nz) {
    this.vel.x += nx * strength * 6
    this.vel.y += nz * strength * 6
    this.vel.multiplyScalar(0.72)
    this.pendingImpact = Math.max(this.pendingImpact, strength)
    this.shake = Math.max(this.shake, strength * 1.1)
    this.impactFlash = Math.max(this.impactFlash || 0, strength)
  }

  get speedKmh() {
    return Math.abs(this.forwardSpeed) * 3.6
  }

  get gear() {
    if (this.forwardSpeed < -0.5) return 'R'
    if (this.speed < 0.6) return 'N'
    const kmh = this.speedKmh
    if (kmh < 28) return '1'
    if (kmh < 58) return '2'
    if (kmh < 92) return '3'
    if (kmh < 128) return '4'
    if (kmh < 170) return '5'
    return '6'
  }
}

import * as THREE from 'three'
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js'
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js'
import { clamp, rand } from './utils.js'
import { makeBlobShadowTexture, makeGlowTexture } from './textures.js'

const MAX_CARS = 18

function colorize(geometry, color) {
  const count = geometry.attributes.position.count
  const array = new Float32Array(count * 3)
  const c = new THREE.Color(color)
  for (let i = 0; i < count; i++) {
    array[i * 3] = c.r
    array[i * 3 + 1] = c.g
    array[i * 3 + 2] = c.b
  }
  geometry.setAttribute('color', new THREE.BufferAttribute(array, 3))
  return geometry
}

function buildCarGeometry() {
  const parts = []
  const tub = new RoundedBoxGeometry(1.78, 0.5, 4.0, 3, 0.12)
  tub.translate(0, 0.6, 0)
  parts.push(colorize(tub, 0xffffff))

  const cabin = new RoundedBoxGeometry(1.5, 0.5, 2.0, 3, 0.12)
  cabin.translate(0, 1.02, 0.12)
  parts.push(colorize(cabin, 0x0a1218))

  const hood = new RoundedBoxGeometry(1.66, 0.14, 1.1, 2, 0.06)
  hood.translate(0, 0.82, 1.42)
  parts.push(colorize(hood, 0xf2f2f2))

  for (const x of [-0.82, 0.82]) {
    for (const z of [-1.32, 1.32]) {
      const wheel = new THREE.CylinderGeometry(0.31, 0.31, 0.22, 14, 1)
      wheel.rotateZ(Math.PI / 2)
      wheel.translate(x, 0.32, z)
      parts.push(colorize(wheel, 0x050506))
    }
  }
  return mergeGeometries(parts)
}

function buildLightGeometry() {
  const parts = []
  for (const x of [-0.55, 0.55]) {
    const head = new THREE.BoxGeometry(0.4, 0.1, 0.06)
    head.translate(x, 0.68, 2.02)
    parts.push(colorize(head, new THREE.Color(3.2, 3.2, 3.0)))

    const tail = new THREE.BoxGeometry(0.36, 0.09, 0.06)
    tail.translate(x, 0.7, -2.02)
    parts.push(colorize(tail, new THREE.Color(3.0, 0.08, 0.16)))
  }
  return mergeGeometries(parts)
}

export class Traffic {
  constructor(scene) {
    this.scene = scene
    this.cars = []
    this.time = 0
    this.nearMissEvent = null
    this.hitEvent = null

    const geometry = buildCarGeometry()
    const material = new THREE.MeshStandardMaterial({
      vertexColors: true,
      metalness: 0.72,
      roughness: 0.34,
      envMapIntensity: 1.5,
    })
    this.mesh = new THREE.InstancedMesh(geometry, material, MAX_CARS)
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.mesh.frustumCulled = false
    this.mesh.count = 0
    this.scene.add(this.mesh)

    const lightGeo = buildLightGeometry()
    const lightMat = new THREE.MeshBasicMaterial({
      vertexColors: true,
      toneMapped: false,
      fog: true,
    })
    this.lightMesh = new THREE.InstancedMesh(lightGeo, lightMat, MAX_CARS)
    this.lightMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.lightMesh.frustumCulled = false
    this.lightMesh.count = 0
    this.scene.add(this.lightMesh)

    // contact shadows
    const shadowGeo = new THREE.PlaneGeometry(2.4, 4.8)
    shadowGeo.rotateX(-Math.PI / 2)
    const shadowMat = new THREE.MeshBasicMaterial({
      map: makeBlobShadowTexture(64),
      transparent: true,
      opacity: 0.8,
      depthWrite: false,
      toneMapped: false,
    })
    this.shadowMesh = new THREE.InstancedMesh(shadowGeo, shadowMat, MAX_CARS)
    this.shadowMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage)
    this.shadowMesh.frustumCulled = false
    this.shadowMesh.count = 0
    this.shadowMesh.renderOrder = 1
    this.scene.add(this.shadowMesh)

    // dynamic headlight glows
    const glowGeo = new THREE.BufferGeometry()
    this.glowPositions = new Float32Array(MAX_CARS * 2 * 3)
    this.glowColors = new Float32Array(MAX_CARS * 2 * 3)
    glowGeo.setAttribute('position', new THREE.BufferAttribute(this.glowPositions, 3))
    glowGeo.setAttribute('color', new THREE.BufferAttribute(this.glowColors, 3))
    const glowMat = new THREE.PointsMaterial({
      size: 1.5,
      map: makeGlowTexture(64),
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      vertexColors: true,
      sizeAttenuation: true,
      toneMapped: false,
      fog: false,
    })
    this.glowPoints = new THREE.Points(glowGeo, glowMat)
    this.glowPoints.frustumCulled = false
    this.glowPoints.renderOrder = 4
    this.scene.add(this.glowPoints)
    this.glowGeometry = glowGeo

    const palette = [
      0xb31f2e, 0x8d939c, 0x1c3f6e, 0x121216, 0xd9a516, 0xe8e8e8, 0x2b5f4a, 0x5a2b6e,
    ]
    this.palette = palette.map((c) => new THREE.Color(c))

    this.dummy = new THREE.Object3D()
    this.dummy.rotation.order = 'YXZ'
  }

  reset(playerPos) {
    this.cars.length = 0
    this.mesh.count = 0
    this.lightMesh.count = 0
    this.shadowMesh.count = 0
    for (let i = 0; i < MAX_CARS; i++) {
      this.spawnCar(playerPos, i)
    }
    this.updateMatrices()
  }

  spawnCar(playerPos, forceIndex = null) {
    const axis = Math.random() > 0.5 ? 'z' : 'x'
    const dir = Math.random() > 0.5 ? 1 : -1
    let x
    let z
    let heading
    if (axis === 'z') {
      const base = Math.round((playerPos.x + rand(-90, 90)) / 80) * 80
      x = base + dir * 4.6
      z = playerPos.z + rand(-260, 300)
      if (Math.abs(z - playerPos.z) < 55) z = playerPos.z + 70 + Math.random() * 120
      heading = dir > 0 ? 0 : Math.PI
    } else {
      const base = Math.round((playerPos.z + rand(-90, 90)) / 80) * 80
      z = base + dir * 4.6
      x = playerPos.x + rand(-260, 300)
      if (Math.abs(x - playerPos.x) < 55) x = playerPos.x + 70 + Math.random() * 120
      heading = dir > 0 ? Math.PI / 2 : -Math.PI / 2
    }

    // avoid stacking cars
    for (let attempt = 0; attempt < 6; attempt++) {
      const tooClose = this.cars.some((c) => Math.hypot(c.x - x, c.z - z) < 14)
      if (!tooClose) break
      if (axis === 'z') z += 22 * dir
      else x += 22 * dir
    }

    const car = {
      x,
      z,
      heading,
      speed: rand(8, 17),
      color: this.palette[Math.floor(Math.random() * this.palette.length)],
      nearMissCooldown: 0,
      hitCooldown: 0,
      wobble: Math.random() * Math.PI * 2,
    }
    if (forceIndex !== null && forceIndex < this.cars.length) this.cars[forceIndex] = car
    else this.cars.push(car)
    return car
  }

  update(dt, player, playerSpeed, playerHeading) {
    this.time += dt
    this.nearMissEvent = null
    this.hitEvent = null

    for (let i = 0; i < this.cars.length; i++) {
      const car = this.cars[i]
      car.nearMissCooldown = Math.max(0, car.nearMissCooldown - dt)
      car.hitCooldown = Math.max(0, car.hitCooldown - dt)
      car.x += Math.sin(car.heading) * car.speed * dt
      car.z += Math.cos(car.heading) * car.speed * dt

      const dx = car.x - player.pos.x
      const dz = car.z - player.pos.y
      const distance = Math.hypot(dx, dz)

      if (distance > 330) {
        this.spawnCar(player.pos, i)
        continue
      }

      // player collision
      if (distance < 2.9 && car.hitCooldown <= 0) {
        const nx = dx / (distance || 1)
        const nz = dz / (distance || 1)
        player.pos.x -= nx * (2.9 - distance) * 0.6
        player.pos.y -= nz * (2.9 - distance) * 0.6
        const rel = Math.abs(playerSpeed)
        const strength = clamp(rel / 40, 0.25, 1)
        player.applyTrafficHit(strength, -nx, -nz)
        car.hitCooldown = 1.2
        this.hitEvent = { strength, x: car.x, z: car.z }
      }

      // near miss
      if (
        distance > 2.9 &&
        distance < 7.2 &&
        Math.abs(playerSpeed) > 13 &&
        car.nearMissCooldown <= 0
      ) {
        car.nearMissCooldown = 2.5
        this.nearMissEvent = { x: car.x, z: car.z }
      }
    }

    this.updateMatrices()
  }

  updateMatrices() {
    const dummy = this.dummy
    const count = this.cars.length
    for (let i = 0; i < count; i++) {
      const car = this.cars[i]
      dummy.position.set(car.x, 0, car.z)
      dummy.rotation.set(0, car.heading, 0)
      dummy.scale.set(1, 1, 1)
      dummy.updateMatrix()
      this.mesh.setMatrixAt(i, dummy.matrix)
      this.lightMesh.setMatrixAt(i, dummy.matrix)
      this.shadowMesh.setMatrixAt(i, dummy.matrix)
      this.mesh.setColorAt(i, car.color)

      const sin = Math.sin(car.heading)
      const cos = Math.cos(car.heading)
      const headX = car.x + sin * 2.05
      const headZ = car.z + cos * 2.05
      const tailX = car.x - sin * 2.05
      const tailZ = car.z - cos * 2.05
      const p = this.glowPositions
      p[i * 6] = headX
      p[i * 6 + 1] = 0.7
      p[i * 6 + 2] = headZ
      p[i * 6 + 3] = tailX
      p[i * 6 + 4] = 0.72
      p[i * 6 + 5] = tailZ
      const c = this.glowColors
      c[i * 6] = 1.6
      c[i * 6 + 1] = 1.8
      c[i * 6 + 2] = 2.0
      c[i * 6 + 3] = 1.8
      c[i * 6 + 4] = 0.05
      c[i * 6 + 5] = 0.12
    }

    this.mesh.count = count
    this.lightMesh.count = count
    this.shadowMesh.count = count
    this.mesh.instanceMatrix.needsUpdate = true
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true
    this.lightMesh.instanceMatrix.needsUpdate = true
    this.shadowMesh.instanceMatrix.needsUpdate = true
    this.glowGeometry.setDrawRange(0, count * 2)
    this.glowGeometry.attributes.position.needsUpdate = true
    this.glowGeometry.attributes.color.needsUpdate = true
  }
}

import { clamp, formatScore, formatTime, loadBest } from './utils.js'

const $ = (id) => document.getElementById(id)

export class Hud {
  constructor(game) {
    this.game = game
    this.el = {
      hud: $('hud'),
      score: $('score'),
      combo: $('combo'),
      comboFill: $('comboFill'),
      timer: $('timer'),
      timerFill: $('timerFill'),
      checkpointText: $('checkpointText'),
      speed: $('speed'),
      speedArc: $('speedArc'),
      gear: $('gear'),
      boostFill: $('boostFill'),
      boostState: $('boostState'),
      driftBadge: $('driftBadge'),
      driftScore: $('driftScore'),
      toastLayer: $('toastLayer'),
      countdown: $('countdown'),
      damageFlash: $('damageFlash'),
      minimap: $('minimap'),
      startScreen: $('startScreen'),
      pauseScreen: $('pauseScreen'),
      overScreen: $('overScreen'),
      loadingScreen: $('loadingScreen'),
      loaderFill: $('loaderFill'),
      bestScore: $('bestScore'),
      pauseScore: $('pauseScore'),
      pauseTime: $('pauseTime'),
      pauseSpeed: $('pauseSpeed'),
      finalScore: $('finalScore'),
      newBest: $('newBest'),
      statDistance: $('statDistance'),
      statTopSpeed: $('statTopSpeed'),
      statDrift: $('statDrift'),
      statCheckpoints: $('statCheckpoints'),
      rotateHint: $('rotateHint'),
      qualityLabel: $('qualityLabel'),
      soundToggle: $('soundToggle'),
      tiltToggle: $('tiltToggle'),
      qualityToggle: $('qualityToggle'),
      howPanel: $('howPanel'),
    }

    this.mapCtx = this.el.minimap.getContext('2d')
    this.mapSize = 220
    this.mapScale = 0.3
    this.mapTimer = 0
    this.toastTimer = null
    this.lastScore = 0
    this.lastSpeed = 0
    this.best = loadBest()
    this.el.bestScore.textContent = formatScore(this.best)
    this.boosting = false

    this.wire()
  }

  wire() {
    const ui = () => this.game.audio.ui()
    $('startBtn').addEventListener('click', () => {
      ui()
      this.game.startRun()
    })
    $('pauseBtn').addEventListener('click', () => {
      ui()
      this.game.pause()
    })
    $('resumeBtn').addEventListener('click', () => {
      ui()
      this.game.resume()
    })
    $('quitBtn').addEventListener('click', () => {
      ui()
      this.game.endRun(true)
    })
    $('retryBtn').addEventListener('click', () => {
      ui()
      this.game.startRun()
    })
    $('menuBtn').addEventListener('click', () => {
      ui()
      this.game.backToMenu()
    })
    this.el.soundToggle.addEventListener('click', () => {
      const muted = this.game.toggleSound()
      this.el.soundToggle.setAttribute('aria-pressed', String(!muted))
      ui()
    })
    this.el.tiltToggle.addEventListener('click', async () => {
      const enabled = await this.game.toggleTilt()
      this.el.tiltToggle.setAttribute('aria-pressed', String(enabled))
      ui()
    })
    this.el.qualityToggle.addEventListener('click', () => {
      this.game.cycleQuality()
      ui()
    })
    $('howBtn').addEventListener('click', () => {
      ui()
      this.el.howPanel.classList.toggle('is-hidden')
    })
    $('howClose').addEventListener('click', () => {
      ui()
      this.el.howPanel.classList.add('is-hidden')
    })
    $('rotateDismiss').addEventListener('click', () => {
      this.el.rotateHint.classList.remove('is-on')
    })
  }

  setQualityLabel(quality) {
    this.el.qualityLabel.textContent = `QUALITY ${quality.toUpperCase()}`
  }

  setSound(enabled) {
    this.el.soundToggle.setAttribute('aria-pressed', String(enabled))
  }

  setTilt(enabled) {
    this.el.tiltToggle.setAttribute('aria-pressed', String(enabled))
  }

  setLoading(progress, text) {
    this.el.loaderFill.style.width = `${Math.round(progress * 100)}%`
    if (text) {
      const label = this.el.loadingScreen.querySelector('.loader-text')
      if (label) label.textContent = text
    }
  }

  hideLoading() {
    this.el.loadingScreen.classList.add('is-hidden')
  }

  showHud() {
    this.el.hud.classList.remove('is-hidden')
    this.el.hud.setAttribute('aria-hidden', 'false')
  }

  hideHud() {
    this.el.hud.classList.add('is-hidden')
    this.el.hud.setAttribute('aria-hidden', 'true')
  }

  showStart() {
    this.el.startScreen.classList.remove('is-hidden')
    this.el.pauseScreen.classList.add('is-hidden')
    this.el.overScreen.classList.add('is-hidden')
    this.el.bestScore.textContent = formatScore(this.best)
  }

  hideStart() {
    this.el.startScreen.classList.add('is-hidden')
  }

  showPause(stats) {
    this.el.pauseScreen.classList.remove('is-hidden')
    this.el.pauseScore.textContent = formatScore(stats.score)
    this.el.pauseTime.textContent = formatTime(stats.time)
    this.el.pauseSpeed.textContent = `${Math.round(stats.speed)}`
  }

  hidePause() {
    this.el.pauseScreen.classList.add('is-hidden')
  }

  showOver(stats) {
    this.el.overScreen.classList.remove('is-hidden')
    this.el.finalScore.textContent = formatScore(stats.score)
    this.el.statDistance.textContent = `${formatScore(stats.distance)} m`
    this.el.statTopSpeed.textContent = `${Math.round(stats.topSpeed)} km/h`
    this.el.statDrift.textContent = formatScore(stats.driftScore)
    this.el.statCheckpoints.textContent = String(stats.checkpoints)
    this.el.newBest.classList.toggle('is-hidden', !stats.newBest)
    if (stats.newBest) {
      this.best = stats.score
      this.el.bestScore.textContent = formatScore(this.best)
    }
    this.hideHud()
  }

  hideOver() {
    this.el.overScreen.classList.add('is-hidden')
  }

  showRotateHint() {
    this.el.rotateHint.classList.add('is-on')
  }

  toast(text, variant = '', duration = 1600) {
    const node = document.createElement('div')
    node.className = `toast ${variant}`.trim()
    node.textContent = text
    this.el.toastLayer.appendChild(node)
    while (this.el.toastLayer.children.length > 3) {
      this.el.toastLayer.firstChild.remove()
    }
    setTimeout(() => node.remove(), duration + 400)
  }

  countdown(text) {
    const node = this.el.countdown
    node.textContent = text
    node.classList.remove('is-on')
    void node.offsetWidth
    node.classList.add('is-on')
  }

  damage(strength) {
    this.el.damageFlash.style.opacity = String(clamp(strength * 0.9, 0, 0.9))
  }

  update(state, dt) {
    const { score, combo, timer, boost, driftScore, checkpointDistance } = state
    this.el.score.textContent = formatScore(score)
    this.el.combo.textContent = `×${combo.toFixed(1)}`
    this.el.combo.classList.toggle('is-hot', combo > 2)
    this.el.comboFill.style.width = `${clamp((combo - 1) / 7, 0, 1) * 100}%`

    this.el.timer.textContent = formatTime(timer)
    this.el.timer.classList.toggle('is-low', timer < 10)
    this.el.timerFill.style.width = `${clamp(timer / 60, 0, 1) * 100}%`
    this.el.timerFill.classList.toggle('is-low', timer < 10)

    if (checkpointDistance != null) {
      this.el.checkpointText.textContent = `CHECKPOINT ${Math.max(0, Math.round(checkpointDistance))}m`
    } else {
      this.el.checkpointText.textContent = 'CHECKPOINT CLEARED'
    }

    const kmh = Math.round(state.speed)
    this.el.speed.textContent = String(kmh)
    const ratio = clamp(kmh / 260, 0, 1)
    this.el.speedArc.style.strokeDasharray = `${ratio * 75} 100`
    this.el.speedArc.style.stroke =
      ratio > 0.82 ? '#ff2fb3' : ratio > 0.6 ? '#8b5cff' : '#4df3ff'
    this.el.gear.textContent = state.gear

    this.el.boostFill.style.width = `${clamp(boost, 0, 100)}%`
    const active = state.boosting
    this.el.boostState.textContent = active ? 'BURN' : boost > 98 ? 'READY' : `${Math.round(boost)}%`
    this.el.boostState.classList.toggle('is-active', active)
    this.el.boostState.classList.toggle('is-ready', !active && boost > 98)
    const boostBtn = document.querySelector('.boost-btn')
    if (boostBtn) boostBtn.classList.toggle('is-armed', boost > 98 && !active)

    this.el.driftBadge.classList.toggle('is-on', driftScore > 0)
    if (driftScore > 0) this.el.driftScore.textContent = formatScore(driftScore)

    this.mapTimer -= dt
    if (this.mapTimer <= 0) {
      this.mapTimer = 0.075
      this.drawMinimap()
    }
  }

  drawMinimap() {
    const ctx = this.mapCtx
    const size = this.mapSize
    const half = size / 2
    const game = this.game
    const player = game.player
    const scale = this.mapScale
    const px = player.pos.x
    const pz = player.pos.y

    ctx.clearRect(0, 0, size, size)
    ctx.save()
    ctx.beginPath()
    ctx.arc(half, half, half - 5, 0, Math.PI * 2)
    ctx.clip()

    const bg = ctx.createRadialGradient(half, half, 10, half, half, half)
    bg.addColorStop(0, 'rgba(10,24,38,0.92)')
    bg.addColorStop(1, 'rgba(3,8,16,0.96)')
    ctx.fillStyle = bg
    ctx.fillRect(0, 0, size, size)

    const worldToMap = (wx, wz) => [half + (wx - px) * scale, half - (wz - pz) * scale]

    // roads
    const range = 34
    const baseX = Math.floor(px / 80) * 80
    const baseZ = Math.floor(pz / 80) * 80
    ctx.strokeStyle = 'rgba(120, 220, 255, 0.16)'
    ctx.lineWidth = 5
    ctx.beginPath()
    for (let i = -3; i <= 3; i++) {
      const x = baseX + i * 80
      const [mx] = worldToMap(x, 0)
      ctx.moveTo(mx, 0)
      ctx.lineTo(mx, size)
      const z = baseZ + i * 80
      const [, my] = worldToMap(0, z)
      ctx.moveTo(0, my)
      ctx.lineTo(size, my)
    }
    ctx.stroke()

    // buildings from nearby chunks
    ctx.fillStyle = 'rgba(60, 92, 120, 0.34)'
    const ci = Math.floor(px / 80)
    const cj = Math.floor(pz / 80)
    for (let di = -2; di <= 2; di++) {
      for (let dj = -2; dj <= 2; dj++) {
        const chunk = game.city.chunks.get(`${ci + di},${cj + dj}`)
        if (!chunk) continue
        for (const b of chunk.colliders) {
          const [x1, y1] = worldToMap(b.minX, b.maxZ)
          const [x2, y2] = worldToMap(b.maxX, b.minZ)
          if (x2 < -20 || x1 > size + 20 || y2 < -20 || y1 > size + 20) continue
          ctx.fillRect(x1, y1, x2 - x1, y2 - y1)
        }
      }
    }

    // traffic
    if (game.traffic) {
      ctx.fillStyle = 'rgba(255, 90, 110, 0.9)'
      for (const car of game.traffic.cars) {
        const [mx, my] = worldToMap(car.x, car.z)
        if (mx < -10 || mx > size + 10 || my < -10 || my > size + 10) continue
        ctx.beginPath()
        ctx.arc(mx, my, 2, 0, Math.PI * 2)
        ctx.fill()
      }
    }

    // orbs
    if (game.collectibles) {
      ctx.fillStyle = 'rgba(77, 243, 255, 0.8)'
      for (const orb of game.collectibles.orbs) {
        const [mx, my] = worldToMap(orb.x, orb.z)
        if (mx < -10 || mx > size + 10 || my < -10 || my > size + 10) continue
        ctx.fillRect(mx - 1.4, my - 1.4, 2.8, 2.8)
      }
    }

    // checkpoint
    if (game.checkpoints?.target) {
      const cp = game.checkpoints.target
      let [mx, my] = worldToMap(cp.x, cp.z)
      const dx = mx - half
      const dy = my - half
      const dist = Math.hypot(dx, dy)
      const maxR = half - 14
      let edge = false
      if (dist > maxR) {
        mx = half + (dx / dist) * maxR
        my = half + (dy / dist) * maxR
        edge = true
      }
      const pulse = 1 + Math.sin(performance.now() * 0.006) * 0.2
      ctx.save()
      ctx.translate(mx, my)
      ctx.rotate(Math.PI / 4)
      ctx.strokeStyle = '#4df3ff'
      ctx.fillStyle = 'rgba(77,243,255,0.35)'
      ctx.lineWidth = 2
      const s = (edge ? 4 : 5) * pulse
      ctx.fillRect(-s, -s, s * 2, s * 2)
      ctx.strokeRect(-s, -s, s * 2, s * 2)
      ctx.restore()
    }

    // player arrow
    ctx.save()
    ctx.translate(half, half)
    ctx.rotate(player.heading)
    ctx.beginPath()
    ctx.moveTo(0, -8)
    ctx.lineTo(5.5, 6)
    ctx.lineTo(0, 3)
    ctx.lineTo(-5.5, 6)
    ctx.closePath()
    ctx.fillStyle = '#eafcff'
    ctx.shadowColor = '#4df3ff'
    ctx.shadowBlur = 10
    ctx.fill()
    ctx.restore()

    // sweep
    const sweep = ctx.createLinearGradient(0, 0, 0, size)
    sweep.addColorStop(0, 'rgba(77,243,255,0.0)')
    sweep.addColorStop(1, 'rgba(77,243,255,0.05)')
    ctx.fillStyle = sweep
    ctx.fillRect(0, 0, size, size)

    ctx.restore()

    // crosshair ticks
    ctx.strokeStyle = 'rgba(77, 243, 255, 0.28)'
    ctx.lineWidth = 1
    ctx.beginPath()
    for (let i = 0; i < 4; i++) {
      const a = (i * Math.PI) / 2
      const x1 = half + Math.cos(a) * (half - 4)
      const y1 = half + Math.sin(a) * (half - 4)
      const x2 = half + Math.cos(a) * (half - 12)
      const y2 = half + Math.sin(a) * (half - 12)
      ctx.moveTo(x1, y1)
      ctx.lineTo(x2, y2)
    }
    ctx.stroke()
  }
}

