212:       shader.vertexShader = `varying vec3 vWPos;\n${shader.vertexShader}`.replace(
213:         '#include <begin_vertex>',
214:         /* glsl */ `#include <begin_vertex>
215:         vWPos = (modelMatrix * vec4(transformed, 1.0)).xyz;
216:         `,
217:       )
218: 
219:       shader.fragmentShader = /* glsl */ `
220:         varying vec3 vWPos;
221:         uniform float uTime;
222: 
223:         float gHash(vec2 p) {
224:           return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
225:         }
226:         float gNoise(vec2 p) {
227:           vec2 i = floor(p);
228:           vec2 f = fract(p);
229:           vec2 u = f * f * (3.0 - 2.0 * f);
230:           return mix(mix(gHash(i), gHash(i + vec2(1.0, 0.0)), u.x),
231:                      mix(gHash(i + vec2(0.0, 1.0)), gHash(i + vec2(1.0, 1.0)), u.x), u.y);
232:         }
233: 
234:         struct GroundInfo {
235:           vec3 albedo;
236:           float rough;
237:           float metal;
238:           vec3 emissive;
239:         };
240:         GroundInfo gGround;
241: 
242:         GroundInfo groundInfo(vec3 wp) {
243:           vec2 p = wp.xz;
244:           vec2 gp = mod(p, 80.0);
245:           vec2 d = min(gp, 80.0 - gp);
246:           float dmin = min(d.x, d.y);
247: 
248:           float road = 1.0 - smoothstep(8.7, 9.15, dmin);
249:           float walk = (1.0 - smoothstep(11.55, 12.05, dmin)) * (1.0 - road);
250:           float block = clamp(1.0 - road - walk, 0.0, 1.0);
251: 
252:           // lane markings --------------------------------------------------
253:           float dash = step(fract(p.y * 0.125), 0.55);
254:           float dashZ = step(fract(p.x * 0.125), 0.55);
255:           float centerX = (1.0 - smoothstep(0.1, 0.24, d.x)) * step(9.3, d.y) * dash;
256:           float centerZ = (1.0 - smoothstep(0.1, 0.24, d.y)) * step(9.3, d.x) * dashZ;
257:           float edgeX = (1.0 - smoothstep(0.06, 0.18, abs(d.x - 8.25))) * step(9.3, d.y);
258:           float edgeZ = (1.0 - smoothstep(0.06, 0.18, abs(d.y - 8.25))) * step(9.3, d.x);
259:           float crossX = step(9.35, d.x) * (1.0 - step(11.7, d.x)) *
260:                          (1.0 - smoothstep(8.1, 8.6, d.y)) * step(0.5, fract(p.y * 0.9));
261:           float crossZ = step(9.35, d.y) * (1.0 - step(11.7, d.y)) *
262:                          (1.0 - smoothstep(8.1, 8.6, d.x)) * step(0.5, fract(p.x * 0.9));
263:           float markings = clamp(centerX + centerZ + edgeX + edgeZ + crossX * 0.8 + crossZ * 0.8, 0.0, 1.0) * road;
264: 
265:           // surfaces -------------------------------------------------------
266:           float grain = gNoise(p * 2.3) * 0.6 + gNoise(p * 7.0) * 0.4;
267:           vec3 asphalt = vec3(0.032, 0.037, 0.048) * (0.72 + grain * 0.65);
268:           vec3 sidewalk = vec3(0.075, 0.08, 0.095) * (0.8 + grain * 0.45);
269:           float tile = smoothstep(0.0, 0.06, abs(fract(p.x / 2.0) - 0.5)) *
270:                        smoothstep(0.0, 0.06, abs(fract(p.y / 2.0) - 0.5));
271:           sidewalk *= mix(0.72, 1.0, tile);
272:           vec3 blockCol = vec3(0.016, 0.019, 0.028) * (0.8 + grain * 0.5);
273: 
274:           vec3 col = mix(asphalt, sidewalk, walk);
275:           col = mix(col, blockCol, block);
276: 
277:           // wet patches
278:           float pn = gNoise(p * 0.055) * 0.62 + gNoise(p * 0.19) * 0.38;
279:           float puddle = smoothstep(0.57, 0.72, pn) * road * (1.0 - markings * 0.9);
280:           puddle *= smoothstep(0.1, 0.3, gNoise(p * 0.8));
281:           col = mix(col, vec3(0.01, 0.014, 0.024), puddle * 0.72);
282: 
283:           col += markings * vec3(0.9, 0.96, 1.0) * 0.5;
284: 
285:           GroundInfo info;
286:           info.albedo = col;
287:           info.rough = mix(0.82, 0.6, road);
288:           info.rough = mix(info.rough, 0.05, puddle);
289:           info.metal = mix(0.0, 0.65, puddle);
290:           info.emissive = markings * vec3(0.28, 0.34, 0.4) + vec3(0.006, 0.01, 0.02) * road;
291:           return info;
292:         }
293:       ` + shader.fragmentShader
294:         .replace(
295:           '#include <color_fragment>',
296:           /* glsl */ `#include <color_fragment>
297:           gGround = groundInfo(vWPos);
298:           diffuseColor.rgb = gGround.albedo;
299:           `,
300:         )
301:         .replace(
302:           '#include <roughnessmap_fragment>',
303:           /* glsl */ `#include <roughnessmap_fragment>
304:           roughnessFactor = gGround.rough;
305:           `,
306:         )
307:         .replace(
308:           '#include <metalnessmap_fragment>',
309:           /* glsl */ `#include <metalnessmap_fragment>
310:           metalnessFactor = gGround.metal;
311:           `,
312:         )
313:         .replace(
314:           '#include <emissivemap_fragment>',
315:           /* glsl */ `#include <emissivemap_fragment>
316:           totalEmissiveRadiance += gGround.emissive;
317:           `,
318:         )
319:     }
320:     material.customProgramCacheKey = () => 'neondrift-ground-v1'
321: 
322:     const geometry = new THREE.PlaneGeometry(1500, 1500, 1, 1)
323:     geometry.rotateX(-Math.PI / 2)
324:     this.ground = new THREE.Mesh(geometry, material)
325:     this.ground.position.y = 0
326:     this.ground.frustumCulled = false
327:     this.ground.receiveShadow = false
328:     this.scene.add(this.ground)
329:     this.groundMaterial = material
330:   }
