543:   // ------------------------------------------------------------ generation
544: 
545:   generateChunk(i, j) {
546:     const rng = mulberry32(((i * 73856093) ^ (j * 19349663) ^ 0x9e3779b9) >>> 0)
547:     const cx = i * CELL + CELL / 2
548:     const cz = j * CELL + CELL / 2
549:     const chunk = { buildings: [], signs: [], lamps: [], colliders: [] }
550: 
551:     const dist = Math.hypot(cx, cz)
552:     const downtown = clamp(1 - dist / 950, 0.18, 1)
553:     const half = 26
554: 
555:     const addBuilding = (ox, oz, w, d) => {
556:       const x = cx + clamp(ox, -half + w / 2, half - w / 2)
557:       const z = cz + clamp(oz, -half + d / 2, half - d / 2)
558:       let height = (11 + Math.pow(rng(), 2.1) * 52) * (0.55 + downtown * 1.25)
559:       if (rng() > 0.9) height += 25 + rng() * 45
560:       height = Math.min(height, 145)
561:       const hue = 0.56 + rng() * 0.13
562:       const color = new THREE.Color().setHSL(hue, 0.28 + rng() * 0.2, 0.05 + rng() * 0.055)
563:       const building = {
564:         x, z, w, d, h: height,
565:         color,
566:         seed: rng() * 97,
567:         crown: rng() < 0.42,
568:         crownColor: NEON_COLORS[Math.floor(rng() * NEON_COLORS.length)].clone().multiplyScalar(1.5),
569:         roofProps: [],
570:         antenna: height > 55 && rng() < 0.7,
571:       }
572: 
573:       if (rng() < 0.35) {
574:         building.roofProps.push({
575:           x: x + rand(-w * 0.22, w * 0.22),
576:           z: z + rand(-d * 0.22, d * 0.22),
577:           w: 2 + rng() * 4,
578:           h: 1.2 + rng() * 3.4,
579:           d: 2 + rng() * 4,
580:         })
581:       }
582: 
583:       chunk.buildings.push(building)
584:       chunk.colliders.push({
585:         minX: x - w / 2,
586:         maxX: x + w / 2,
587:         minZ: z - d / 2,
588:         maxZ: z + d / 2,
589:       })
590: 
591:       // Signs face the closest street.
592:       if (rng() < 0.62) {
593:         const edges = [
594:           { dist: x - (cx - 28), face: 'left' },
595:           { dist: cx + 28 - x, face: 'right' },
596:           { dist: z - (cz - 28), face: 'back' },
597:           { dist: cz + 28 - z, face: 'front' },
598:         ].sort((a, b) => a.dist - b.dist)
599:         const face = edges[0].face
600:         const faceWidth = face === 'left' || face === 'right' ? d : w
601:         const signW = Math.min(faceWidth - 2.5, 4.8 + rng() * 4.5)
602:         const signH = signW * (0.42 + rng() * 0.1)
603:         const y = clamp(5.5 + rng() * 24, 5.5, Math.max(6, height - 4))
604:         const along = (rng() - 0.5) * Math.max(0, faceWidth - signW - 2)
605:         let sx = x
606:         let sz = z
607:         let ry = 0
608:         if (face === 'left') { sx = x - w / 2 - 0.1; sz = z + along; ry = -Math.PI / 2 }
609:         if (face === 'right') { sx = x + w / 2 + 0.1; sz = z + along; ry = Math.PI / 2 }
610:         if (face === 'back') { sx = x + along; sz = z - d / 2 - 0.1; ry = Math.PI }
611:         if (face === 'front') { sx = x + along; sz = z + d / 2 + 0.1; ry = 0 }
612:         const variant = Math.floor(rng() * this.signTextures.length)
613:         chunk.signs.push({ x: sx, y, z: sz, ry, w: signW, h: signH, variant })
614:       }
615:     }
616: 
617:     const layout = rng()
618:     if (layout < 0.4) {
619:       addBuilding(rand(-4, 4), rand(-4, 4), 22 + rng() * 20, 22 + rng() * 20)
620:     } else if (layout < 0.72) {
621:       const w = 17 + rng() * 8
622:       const d = 38 + rng() * 10
623:       addBuilding(-16, rand(-2, 2), w, d)
624:       addBuilding(16, rand(-2, 2), w, d)
625:     } else {
626:       const w = 17 + rng() * 7
627:       const d = 17 + rng() * 7
628:       addBuilding(-15, -15, w, d)
629:       addBuilding(15, -15, w, d)
630:       addBuilding(-15, 15, w, d)
631:       addBuilding(15, 15, w, d)
632:     }
633: 
634:     // Streetlights on each side of the block.
635:     const sides = [
636:       { x: cx - 29.5, z: cz, ry: Math.PI, hx: cx - 31.6, hz: cz },
637:       { x: cx + 29.5, z: cz, ry: 0, hx: cx + 31.6, hz: cz },
638:       { x: cx, z: cz - 29.5, ry: Math.PI / 2, hx: cx, hz: cz - 31.6 },
639:       { x: cx, z: cz + 29.5, ry: -Math.PI / 2, hx: cx, hz: cz + 31.6 },
640:     ]
641:     for (const side of sides) {
642:       const warm = rng() > 0.4
643:       chunk.lamps.push({
644:         ...side,
645:         color: warm ? new THREE.Color(1.0, 0.78, 0.48) : new THREE.Color(0.55, 0.88, 1.0),
646:       })
647:     }
648: 
649:     return chunk
650:   }
651: 
652:   ensureChunks(px, pz) {
653:     const ci = Math.floor(px / CELL)
654:     const cj = Math.floor(pz / CELL)
655:     if (this.lastChunk && this.lastChunk.i === ci && this.lastChunk.j === cj) return false
656:     this.lastChunk = { i: ci, j: cj }
657: 
658:     const keys = []
659:     for (let di = -CHUNK_RADIUS; di <= CHUNK_RADIUS; di++) {
660:       for (let dj = -CHUNK_RADIUS; dj <= CHUNK_RADIUS; dj++) {
661:         const i = ci + di
662:         const j = cj + dj
663:         const key = `${i},${j}`
664:         keys.push(key)
665:         if (!this.chunks.has(key)) this.chunks.set(key, this.generateChunk(i, j))
666:       }
667:     }
668:     this.activeKeys = keys
669: 
670:     // Drop far-away chunks so memory stays flat.
671:     if (this.chunks.size > 220) {
672:       const active = new Set(keys)
673:       for (const key of this.chunks.keys()) {
674:         if (!active.has(key)) this.chunks.delete(key)
675:       }
676:     }
677:     this.rebuildInstances()
678:     return true
679:   }
680: 
681:   rebuildInstances() {
682:     const dummy = new THREE.Object3D()
683:     let bi = 0
684:     let pi = 0
685:     let ai = 0
686:     let ci = 0
687:     let li = 0
688:     let pi2 = 0
689:     let gi = 0
690:     const signCounts = new Array(this.signMeshes.length).fill(0)
691:     const glowPos = this.glowPositions
692:     const glowCol = this.glowColors
693: 
694:     const addGlow = (x, y, z, color, scale = 1) => {
695:       if (gi >= MAX_GLOWS) return
696:       glowPos[gi * 3] = x
697:       glowPos[gi * 3 + 1] = y
698:       glowPos[gi * 3 + 2] = z
699:       glowCol[gi * 3] = color.r * scale
700:       glowCol[gi * 3 + 1] = color.g * scale
701:       glowCol[gi * 3 + 2] = color.b * scale
702:       gi++
703:     }
704: 
705:     for (const key of this.activeKeys) {
706:       const chunk = this.chunks.get(key)
707:       if (!chunk) continue
708: 
709:       for (const b of chunk.buildings) {
710:         if (bi < MAX_BUILDINGS) {
711:           dummy.position.set(b.x, b.h / 2, b.z)
712:           dummy.rotation.set(0, 0, 0)
713:           dummy.scale.set(b.w, b.h, b.d)
714:           dummy.updateMatrix()
715:           this.buildingMesh.setMatrixAt(bi, dummy.matrix)
716:           this.buildingMesh.setColorAt(bi, b.color)
717:           this.buildingSeeds.array[bi] = b.seed
718:           bi++
719:         }
720: 
721:         if (b.crown && ci < MAX_CROWNS) {
722:           dummy.position.set(b.x, b.h - 0.12, b.z)
723:           dummy.rotation.set(0, 0, 0)
724:           dummy.scale.set(b.w + 0.45, 0.28, b.d + 0.45)
