```glsl
void getWindows(vec3 n, vec3 local, vec3 scale, float seed,
                out float mask, out vec3 emis) {
  float side = 1.0 - step(0.5, abs(n.y));
  vec3 wp = vWorldPos;

  vec2 plane;
  if (abs(n.x) > 0.5) plane = vec2(wp.z, wp.y);
  else if (abs(n.z) > 0.5) plane = vec2(wp.x, wp.y);
  else plane = vec2(wp.x, wp.z);

  vec2 uv = plane / vec2(2.0, 2.6);
  vec2 cell = floor(uv);
  vec2 f = fract(uv);

  vec2 fw = fwidth(uv);
  float aa = clamp(1.0 - max(fw.x, fw.y) * 1.7, 0.0, 1.0);

  // Wide mullions: window occupies the middle 52% of each cell.
  float wx = smoothstep(0.24, 0.30, f.x) * (1.0 - smoothstep(0.70, 0.76, f.x));
  float wy = smoothstep(0.22, 0.28, f.y) * (1.0 - smoothstep(0.72, 0.78, f.y));
  mask = wx * wy * side;

  // Per-building palette so a tower reads as one building, not confetti.
  float palette = ndHash(vec2(seed * 0.37, seed * 1.91), seed);
  vec3 tintA = vec3(1.0, 0.62, 0.34); // amber
  vec3 tintB = vec3(0.45, 0.78, 1.0); // cool blue
  vec3 tintC = vec3(1.0, 0.4, 0.75);  // neon pink
  vec3 base = palette < 0.5 ? tintA : (palette < 0.85 ? tintB : tintC);

  // Occupancy is coherent: lit floors, lit columns, and a few individual offices.
  float floorH = ndHash(vec2(seed, cell.y), seed + 1.0);
  float colH = ndHash(vec2(cell.x, seed), seed + 2.0);
  float office = ndHash(cell, seed + 3.0);

  float litFloor = step(0.72, floorH);
  float litCol = step(0.86, colH);
  float litOffice = step(0.90, office);
  float lit = max(max(litFloor, litCol * 0.75), litOffice);

  // Some windows on a lit floor are still dark.
  lit *= step(0.12, ndHash(cell + 7.0, seed + 5.0));

  float level = 0.35 + 0.65 * ndHash(cell + 5.0, seed + 6.0);
  float heightFade = mix(1.0, 0.45, smoothstep(4.0, 130.0, wp.y));

  vec3 warmShift = mix(base, vec3(1.0, 0.9, 0.72), 0.25);
  vec3 c = mix(base, warmShift, step(0.5, office));
  emis = c * lit * level * 0.55 * heightFade * aa;

  // dark glass still catches a hint of city light
  emis += vec3(0.008, 0.016, 0.03) * mask;
  // mullions / frame
  emis += vec3(0.012, 0.02, 0.034) * (1.0 - mask) * side * heightFade;

  // ground-floor shopfront band
  float baseBand = (1.0 - smoothstep(0.0, 3.4, wp.y)) * side;
  float shop = step(0.45, ndHash(vec2(floor(wp.x / 6.0), floor(wp.z / 6.0)) + seed, seed + 4.0));
  emis += mix(vec3(1.0, 0.55, 0.25), vec3(0.25, 0.85, 1.0), step(0.5, palette)) * baseBand * shop * 0.3;
}
